pragma solidity >=0.8.0;

contract IntDivOverflowWidths {
    uint256 public count;
    int8 public last8;

    function div8(int8 x, int8 y) external returns (int8) {
        int8 r = x / y;
        count += 1;
        last8 = r;
        return r;
    }

    function okDiv8() external returns (int8) {
        int8 r = int8(-7) / int8(2);
        count += 1;
        last8 = r;
        return r;
    }
}
